"""Shift reports (SV-2.3, #295): the FurnaceMind Reports tab's shift report, generated by the twin-worker and served by
the twin-api.

The report is ``reports.furnace_report``'s, composed from the building blocks of its ``ShiftReportService`` exactly as
the Reports tab composes it (``ShiftReportService.generate_document``): the shift's online, HM/slag, charge and analysis
data are fetched and built into ``ShiftReportData`` (``build``); with the narrative, the previous shift's metrics are
built as well (``build_previous``) and both go to the LLM (``ShiftAnalyser`` with page 7's ``OpenRouterClient``);
``document`` renders the tables. Differences from the tab: the LLM call has a time limit (``LLM_TIMEOUT_S``, no SDK
retries) and is tried once more after a failure or an empty answer (``LLM_TRIES``, ``LLM_RETRY_DELAY_S`` apart); when
the second try fails as well the report is kept without narrative (``narrative_status`` failed, with the errors). The
tab instead shows the report without analysis after one failed call.

Kinds of report: ``closed``, the shift that ended before the schedule slot (``report.shift`` at 06:20, 14:20 and 22:20
IST: shifts C, A and B), or a shift named by the request; ``live``, the running shift on demand (``report.live``). The
window of a live report is the whole shift, so its data run to the time of the request and its theoretical production
is the mean rate × 8 h, as the tab shows a running shift.

Building blocks (``generate``, ``write_narrative``, ``report_data``, ``document_data``, ``store_values``) and views of
stored rows (``summary_data``, ``detail_data``) for the worker and the API. No Streamlit or ``ui`` import.

KPI status (SV-2.4, #296): ``load_thresholds`` reads ``config/shift_report.yml -> status_thresholds`` at every call;
``kpi_checks`` evaluates a stored report's ETA CO, fuel rate, RAFT and permeability against them through
``reports.furnace_report.status``, the rule the builder applies to the report's status.
"""

from __future__ import annotations

import logging
import math
import re
import time
from collections.abc import Callable, Mapping
from dataclasses import asdict, dataclass
from datetime import UTC, date, datetime
from typing import TYPE_CHECKING, Any, Literal

from reports.furnace_report.analyser import ShiftAnalyser
from reports.furnace_report.data import ReportTimeframe, ShiftReportData
from reports.furnace_report.status import ATTENTION_FROM, UNSTABLE_FROM, Thresholds, evaluate, load_thresholds
from reports.furnace_report.timeframe import get_report_timeframe
from reports.rendering import ReportDocument
from utils.shift_windows import last_completed_shift, previous_shift

if TYPE_CHECKING:  # the service imports the data sources (InfluxDB, Neon): loaded by ``generate`` only
    from reports.furnace_report.service import ShiftReportService

log = logging.getLogger(__name__)

#: Time limit of one LLM call, s (the SDK's own retries are turned off: ``LLM_TRIES`` counts every call).
LLM_TIMEOUT_S = 120.0
#: LLM calls per narrative: the first and one retry.
LLM_TRIES = 2
#: Wait before the retry, s.
LLM_RETRY_DELAY_S = 15.0

SHIFT_KEY = re.compile(r"^(\d{4}-\d{2}-\d{2})_([ABC])$")
TEMP_ROWS = ("uptake", "lower_stack", "belly", "skin_flow", "bosh")

ReportKind = Literal["closed", "live"]
NarrativeStatus = Literal["ok", "failed", "skipped"]
Progress = Callable[[float, str], None]


class ReportDataError(RuntimeError):
    """The report's source data could not be fetched or built (InfluxDB or Neon unavailable)."""


@dataclass(frozen=True)
class Shift:
    """A production shift: the IST date of its start and its letter (A 06-14, B 14-22, C 22-06)."""

    date: date
    letter: str

    @property
    def key(self) -> str:
        """``YYYY-MM-DD_A``, the key of ``twin.shift_record`` and ``twin.shift_report``."""
        return f"{self.date:%Y-%m-%d}_{self.letter}"

    def timeframe(self) -> ReportTimeframe:
        return get_report_timeframe("Shift", self.date, self.letter)

    @classmethod
    def parse(cls, key: str) -> Shift:
        match = SHIFT_KEY.match(str(key))
        if not match:
            raise ValueError(f"shift key must read YYYY-MM-DD_A|B|C, got {key!r}")
        return cls(date.fromisoformat(match.group(1)), match.group(2))


def running_shift(now: datetime | None = None) -> Shift:
    """The shift in which ``now`` falls (``utils.shift_windows.last_completed_shift`` returns that shift)."""
    day, letter = last_completed_shift(now or datetime.now(UTC))
    return Shift(day, letter)


def closed_shift(at: datetime | None = None) -> Shift:
    """The shift that ended last before ``at``: C of the day before at 06:20 IST, A at 14:20, B at 22:20."""
    running = running_shift(at)
    day, letter = previous_shift(running.date, running.letter)
    return Shift(day, letter)


@dataclass(frozen=True)
class Narrative:
    """The LLM's analysis of a report, or why there is none."""

    status: NarrativeStatus
    text: str | None = None
    tries: int = 0
    error: str | None = None
    model: str | None = None


@dataclass(frozen=True)
class GeneratedReport:
    shift: Shift
    kind: ReportKind
    data: ShiftReportData
    document: ReportDocument
    narrative: Narrative
    generated_at: datetime


def _short(exc: BaseException, limit: int = 300) -> str:
    text = f"{type(exc).__name__}: {exc}" if str(exc) else type(exc).__name__
    return text if len(text) <= limit else text[: limit - 1] + "…"


def narrative_client() -> Any:
    """Page 7's LLM client (``OpenRouterClient``, default reasoning profile) with the time limit ``LLM_TIMEOUT_S`` and
    no retries inside the SDK. Raises when the client cannot be built (``OPENROUTER_API_KEY`` not set)."""
    from agents.llm.llm_client import OpenRouterClient

    client = OpenRouterClient()
    sdk = getattr(client, "client", None)
    if sdk is not None and hasattr(sdk, "with_options"):
        client.client = sdk.with_options(timeout=LLM_TIMEOUT_S, max_retries=0)
    return client


def write_narrative(
    current: ShiftReportData,
    previous: ShiftReportData | None,
    *,
    client_factory: Callable[[], Any] | None = None,
    tries: int | None = None,
    retry_delay_s: float | None = None,
    sleep: Callable[[float], None] = time.sleep,
    progress: Progress | None = None,
) -> Narrative:
    """The tab's analysis (``ShiftAnalyser``) of ``current`` against ``previous``, tried ``tries`` times (default
    ``LLM_TRIES``, ``LLM_RETRY_DELAY_S`` apart) with the client of ``client_factory`` (default ``narrative_client``); a
    failed narrative carries the error of every try."""
    tries = LLM_TRIES if tries is None else tries
    retry_delay_s = LLM_RETRY_DELAY_S if retry_delay_s is None else retry_delay_s
    try:
        client = (client_factory or narrative_client)()
    except Exception as exc:
        log.warning("shift report narrative: no LLM client (%s)", _short(exc))
        return Narrative("failed", error=f"no LLM client: {_short(exc)}")
    analyser = ShiftAnalyser(client)
    errors: list[str] = []
    for attempt in range(1, tries + 1):
        if progress is not None:
            progress(0.5 + 0.4 * (attempt - 1) / tries, f"Writing the narrative (try {attempt} of {tries})")
        try:
            text = (analyser.analyse(current, previous) or "").strip()
            if not text:
                raise ValueError("the LLM returned an empty narrative")
            model = getattr(client, "last_actual_model", None)
            return Narrative("ok", text=text, tries=attempt, model=model if isinstance(model, str) else None)
        except Exception as exc:
            errors.append(f"try {attempt}: {_short(exc)}")
            log.warning("shift report narrative, try %d of %d failed: %s", attempt, tries, _short(exc))
            if attempt < tries and retry_delay_s > 0:
                sleep(retry_delay_s)
    return Narrative("failed", tries=tries, error="; ".join(errors))


def generate(
    shift: Shift,
    *,
    kind: ReportKind = "closed",
    narrative: bool = True,
    client_factory: Callable[[], Any] | None = None,
    retry_delay_s: float | None = None,
    service: ShiftReportService | None = None,
    progress: Progress | None = None,
) -> GeneratedReport:
    """The report of ``shift`` as the Reports tab composes it, with the narrative tried ``LLM_TRIES`` times.
    Raises ``ReportDataError`` when the shift's data cannot be fetched or built."""
    if service is None:
        from reports.furnace_report.service import ShiftReportService

        service = ShiftReportService()
    timeframe = shift.timeframe()
    if progress is not None:
        progress(0.1, f"Fetching and building the data of shift {shift.key}")
    try:
        current = service.build(timeframe)
    except Exception as exc:
        raise ReportDataError(f"the data of shift {shift.key} could not be fetched or built: {_short(exc)}") from exc
    if narrative:
        if progress is not None:
            progress(0.4, "Building the previous shift for the comparison")
        note = write_narrative(
            current,
            service.build_previous(timeframe),
            client_factory=client_factory,
            retry_delay_s=retry_delay_s,
            progress=progress,
        )
    else:
        note = Narrative("skipped")
    document = service.document(current, note.text or "", timeframe)
    return GeneratedReport(shift, kind, current, document, note, datetime.now(UTC))


# ------------------------------------------------------------------------------------------------- plain values


def _clean(value: Any) -> Any:
    """JSON values: NaN and infinities as None, times and dates as ISO text."""
    if isinstance(value, float):
        return value if math.isfinite(value) else None
    if isinstance(value, datetime | date):
        return value.isoformat()
    if isinstance(value, Mapping):
        return {str(k): _clean(v) for k, v in value.items()}
    if isinstance(value, list | tuple):
        return [_clean(v) for v in value]
    return value


def report_data(report: ShiftReportData) -> dict[str, Any]:
    """``ShiftReportData`` as JSON values: its fields (statistics and temperature rows as objects, with the spread of
    each row), the window length and id."""
    out = asdict(report)
    for name in TEMP_ROWS:
        out[name]["spread_std"] = getattr(report, name).spread_std
    out["duration_h"] = report.duration_hours
    out["window_id"] = report.window_id
    return _clean(out)


def document_data(document: ReportDocument) -> dict[str, Any]:
    """The report's tables and notes as the Reports tab renders them (cells are formatted text)."""
    return _clean(
        {
            "title": document.title,
            "pre_blocks": list(document.pre_blocks),
            "sections": [
                {
                    "title": s.title,
                    "headers": list(s.headers),
                    "rows": [list(r) for r in s.rows],
                    "placement": s.placement,
                }
                for s in document.sections
            ],
            "notes": [{"text": n.text, "placement": n.placement, "kind": n.kind} for n in document.notes],
            "generated_at_ist": document.generated_at_ist,
        }
    )


def _finite(value: Any) -> float | None:
    try:
        v = float(value)
    except (TypeError, ValueError):
        return None
    return v if math.isfinite(v) else None


def store_values(
    report: GeneratedReport, *, job_id: str | None, trigger: Literal["schedule", "user"], requested_by: str
) -> dict[str, Any]:
    """The ``twin.shift_report`` row of a generated report."""
    timeframe = report.shift.timeframe()
    data = report.data
    return {
        "shift_key": report.shift.key,
        "letter": report.shift.letter,
        "shift_start": timeframe.start_ist.astimezone(UTC),
        "shift_end": timeframe.end_ist.astimezone(UTC),
        "kind": report.kind,
        "trigger": trigger,
        "requested_by": requested_by,
        "job_id": job_id,
        "generated_at": report.generated_at,
        "furnace_status": data.status,
        "production_rate_t_h": _finite(data.production_rate),
        "fuel_rate_kg_thm": _finite(data.fuel_rate),
        "coke_rate_kg_thm": _finite(data.coke_rate),
        "pci_rate_kg_thm": _finite(data.pci_rate),
        "etaco_pct": _finite(data.etaco.mean),
        "hm_si_pct": _finite(data.hm_si),
        "narrative_status": report.narrative.status,
        "narrative": report.narrative.text,
        "narrative_error": report.narrative.error,
        "narrative_tries": report.narrative.tries,
        "narrative_model": report.narrative.model,
        "data": report_data(data),
        "document": document_data(report.document),
    }


# ------------------------------------------------------------------------------------------------- stored rows

SUMMARY_FIELDS = (
    "shift_key",
    "kind",
    "trigger",
    "requested_by",
    "job_id",
    "furnace_status",
    "narrative_status",
    "production_rate_t_h",
    "fuel_rate_kg_thm",
    "coke_rate_kg_thm",
    "pci_rate_kg_thm",
    "etaco_pct",
    "hm_si_pct",
)


def _get(row: Any, key: str) -> Any:
    return row.get(key) if isinstance(row, Mapping) else getattr(row, key, None)


def _utc(value: Any) -> datetime | None:
    """A stored time as aware UTC (SQLite returns naive UTC)."""
    if value is None:
        return None
    if isinstance(value, str):
        value = datetime.fromisoformat(value)
    return value.replace(tzinfo=UTC) if value.tzinfo is None else value.astimezone(UTC)


def report_status(narrative_status: str | None) -> Literal["complete", "no_narrative"]:
    """``complete``: data and narrative; ``no_narrative``: data only (the LLM failed after its retry, or the narrative
    was not requested)."""
    return "complete" if narrative_status == "ok" else "no_narrative"


def summary_data(row: Any) -> dict[str, Any]:
    """A stored report without its data, tables and narrative (list view)."""
    out = {k: _get(row, k) for k in SUMMARY_FIELDS}
    key = Shift.parse(out["shift_key"])
    out.update(
        id=str(_get(row, "id")),
        shift=key.letter,
        shift_date=key.date,
        shift_start=_utc(_get(row, "shift_start")),
        shift_end=_utc(_get(row, "shift_end")),
        generated_at=_utc(_get(row, "generated_at")),
        status=report_status(out["narrative_status"]),
    )
    return out


def thresholds_data(thresholds: Thresholds | None = None) -> dict[str, Any]:
    """The status thresholds (default: read from the configuration now) and the flag counts of the status rule."""
    t = thresholds or load_thresholds()
    return {
        "etaco_warn_pct": t.etaco_warn,
        "etaco_crit_pct": t.etaco_crit,
        "fuel_rate_warn_kg_thm": t.fuel_rate_warn,
        "fuel_rate_crit_kg_thm": t.fuel_rate_crit,
        "raft_lo_c": t.raft_lo,
        "raft_hi_c": t.raft_hi,
        "permeability_lo": t.perm_lo,
        "permeability_hi": t.perm_hi,
        "attention_from": ATTENTION_FROM,
        "unstable_from": UNSTABLE_FROM,
    }


def _mean_of(data: Mapping[str, Any], key: str) -> Any:
    stats = data.get(key)
    return stats.get("mean") if isinstance(stats, Mapping) else None


def kpi_checks(data: Mapping[str, Any], thresholds: Thresholds | None = None) -> list[dict[str, Any]]:
    """A stored report's ETA CO, fuel rate, RAFT and permeability (``report_data`` values) against the thresholds
    (default: read from the configuration now): value, level, rule and the Reports tab's flag."""
    checks = evaluate(
        etaco=_mean_of(data, "etaco"),
        fuel_rate=data.get("fuel_rate"),
        raft=_mean_of(data, "raft"),
        perm=_mean_of(data, "permeability"),
        thresholds=thresholds or load_thresholds(),
    )
    return [asdict(c) for c in checks]


def detail_data(row: Any, thresholds: Thresholds | None = None) -> dict[str, Any]:
    """A stored report with its data, tables and narrative, and its KPIs against the thresholds (default: read from
    the configuration now)."""
    data = _get(row, "data") or {}
    return summary_data(row) | {
        "narrative": _get(row, "narrative"),
        "narrative_error": _get(row, "narrative_error"),
        "narrative_tries": _get(row, "narrative_tries") or 0,
        "narrative_model": _get(row, "narrative_model"),
        "data": data,
        "document": _get(row, "document") or {},
        "kpis": kpi_checks(data, thresholds),
    }


def job_result(report: GeneratedReport, report_id: str | None) -> dict[str, Any]:
    """The result of a report job: the stored report's id and headline; without a twin store the whole report."""
    values = store_values(report, job_id=None, trigger="user", requested_by="")
    out: dict[str, Any] = {
        "report_id": report_id,
        "stored": report_id is not None,
        "shift_key": report.shift.key,
        "kind": report.kind,
        "status": report_status(report.narrative.status),
        "furnace_status": report.data.status,
        "narrative_status": report.narrative.status,
        "narrative_tries": report.narrative.tries,
        "narrative_error": report.narrative.error,
    }
    out.update({k: values[k] for k in SUMMARY_FIELDS if k.endswith(("_t_h", "_kg_thm", "_pct"))})
    if report_id is None:
        out.update(narrative=report.narrative.text, data=values["data"], document=values["document"])
    return out


